import{readFileSync}from"node:fs";import{describe,expect,it}from"vitest";
describe("clean-no-outputs summary",()=>{it("labels single-file probes without claiming canonical tree hashes",()=>{const value=JSON.parse(readFileSync("tests/fixtures/evidence/clean-no-outputs-summary-v2.json","utf8"));expect(value).toMatchObject({schemaVersion:"phase4-clean-no-outputs-summary-v2",sourceProbeRelativePath:"src/readiness/currentReleaseIdentity.ts",runtimeProbeRelativePath:"src/server/httpServer.ts"});expect(value.sourceProbeFileSha256).toMatch(/^[a-f0-9]{64}$/u);expect(value.runtimeProbeFileSha256).toMatch(/^[a-f0-9]{64}$/u);expect(value).not.toHaveProperty("sourceTreeSha256");expect(value).not.toHaveProperty("runtimeTreeSha256")})});
